SELECT SQL_NO_CACHE COALESCE(stocktrans.BRANDNAME, 'UNBRANDED') AS keyval, COALESCE(stocktrans.BRANDNAME, 'UNBRANDED') AS label, CAST(SUM(stocktrans.qty * -1) AS DECIMAL(16, 0)) AS qty, CAST(SUM(stocktrans.discountedlinetotal * -1) AS DECIMAL(16, 2)) AS total FROM stocktrans WHERE stocktrans.trandate BETWEEN '0000-00-00' AND CURRENT_DATE AND stocktrans.loccode IN (SELECT loccode FROM locationusers WHERE canview = 1 AND userid = 'JACK') GROUP BY keyval, label ORDER BY total DESC, label ASC 